@tools.register(
    name="delegate_to_team_parallel",
    description=(
        "互いに依存しない複数のタスクを、それぞれ delegate_to_team と同じ"
        "Researcher→Worker パイプラインで並列実行する。"
        "各タスクの指示文(tasks)は事前に自分(Director)で調査し具体的に書くこと。"
        "【重要】tasks は必ず文字列の配列（list[str]）で渡すこと（例: [\"タスク1の説明\", \"タスク2の説明\"]）。"
        "1つのタスクを\"###\"等の区切りで連結した単一の文字列として渡してはならない"
        "（文字列を渡すと1文字ごとに大量のWorkerが起動してしまう）。要素数は最大10件まで。"
        "verify_cmdを指定すると、各タスクのWorker実行後に同じOverlay上でこのコマンドが実行され、"
        "失敗した場合は各Workerがそれぞれ自動修正再試行する（全タスク共通・最大3回）。"
        "省略時でも各タスクのResearcherが適切なコマンドを提案すれば自動採用される。"
    ),
    parameters={
        "type": "object",
        "properties": {
            "tasks": {
                "type": "array",
                "items": {"type": "string"},
                "description": "Workerチームに与えるタスク一覧（各要素が独立した自己完結タスクであること、最大10件）",
            },
            "project_dir": {
                "type": "string",
                "description": "作業対象のプロジェクトディレクトリのフルパス（通常は現在の作業フォルダ）",
                "default": ".",
            },
            "verify_cmd": {
                "type": "string",
                "description": "各タスクのWorker実行後に実行する検証コマンド（全タスク共通）。省略可。",
                "default": "",
            },
        },
        "required": ["tasks"],
    },
)
def delegate_to_team_parallel(tasks: list[str], project_dir: str = ".", verify_cmd: str = "") -> str:
    from .team import run_team_tasks_parallel, _get_team_config
    if isinstance(tasks, str):
        return ("エラー: tasks は文字列ではなく、文字列の配列（list[str]）で渡してください。"
                "例: [\"タスク1の説明\", \"タスク2の説明\"]")
    if not tasks:
        return "エラー: tasks が空です。"
    if len(tasks) > 10:
        return f"エラー: tasks が{len(tasks)}件あります。1回の呼び出しは10件以下に分割してください。"
    results = run_team_tasks_parallel(tasks, project_dir, _get_team_config(), verify_cmd=verify_cmd)
    blocks = []
    for i, r in enumerate(results, 1):
        blocks.append(f"── チーム {i}/{len(results)} ──\n{r}")
    return f"[delegate_to_team_parallel: {len(results)} 件完了]\n\n" + "\n\n".join(blocks)


