# ── search_history ツール ──────────────────────────────────────────
_sessions_dir_for_tool: "Optional[Path]" = None

def set_sessions_dir(path: "Path") -> None:
    global _sessions_dir_for_tool
    _sessions_dir_for_tool = path


@tools.register(
    name="search_history",
    description=(
        "過去のセッションログを検索し、ユーザー入力と回答を返す。"
        "以前のタスクの結果・知見を参照したいときや、作業を再開したいときに使う。"
        "query='' (空文字) にすると最新セッションから順に全件サマリを返す（作業再開時はまずこれを使うこと）。"
        "キーワードを指定すると内容で絞り込む。max_results は多めに指定してよい（デフォルト10）。"
    ),
    parameters={
        "type": "object",
        "properties": {
            "query":       {"type": "string", "description": "検索キーワード（空文字で最新N件をすべて返す）", "default": ""},
            "max_results": {"type": "integer", "description": "最大件数（デフォルト10）", "default": 10},
        },
        "required": [],
    }
)
def search_history(query: str = "", max_results: int = 10) -> str:
    from .commands import _search_sessions, _parse_session_file
    if not _sessions_dir_for_tool or not _sessions_dir_for_tool.exists():
        return "セッションログがまだありません。"

    # 空クエリ → 最新セッションから順にターン一覧を返す
    if not query.strip():
        jsonl_files = sorted(_sessions_dir_for_tool.glob("*.jsonl"), reverse=True)
        lines = [f"[search_history: 最新セッション一覧  {len(jsonl_files)}ファイル]\n"]
        shown = 0
        for jf in jsonl_files:
            s = _parse_session_file(jf)
            if not s:
                continue
            turns = s.get("turns", [])
            lines.append(f"=== {s['file']}  ({len(turns)} ターン  {s.get('model','')}) ===")
            for t in turns:
                user_preview = t["user"][:120].replace("\n", " ")
                ans_preview  = t.get("answer", "")[:120].replace("\n", " ")
                lines.append(f"  Q: {user_preview}")
                if ans_preview:
                    lines.append(f"  A: {ans_preview}")
                shown += 1
                if shown >= max_results:
                    lines.append(f"\n…（{max_results}件表示済み。さらに必要なら max_results を増やすか query で絞り込む）")
                    return "\n".join(lines)
            lines.append("")
        return "\n".join(lines)

    # キーワード検索
    hits = _search_sessions(_sessions_dir_for_tool, query, max_results=max_results)
    if not hits:
        return (
            f"「{query}」に一致するログが見つかりませんでした。\n"
            f"ヒント: query='' で最新セッションの全ターンを確認できます。"
        )
    lines = [f"[search_history: {query}] {len(hits)}件ヒット\n"]
    for i, h in enumerate(hits, 1):
        lines.append(f"--- [{i}] {h['file']}  {h['ts']}")
        lines.append(f"User: {h['full_user']}")
        if h["full_result"]:
            lines.append(f"Result: {h['full_result']}")
        lines.append("")
    return "\n".join(lines)


_pw_context: dict = {}  # {"playwright": ..., "browser": ..., "page": ...}
_pw_lock = threading.Lock()

def _get_browser_page():
    """Playwright ページを lazy init で返す。未インストール時は RuntimeError。"""
    with _pw_lock:
        if "page" not in _pw_context or _pw_context["page"].is_closed():
            try:
                from playwright.sync_api import sync_playwright
            except ImportError:
                raise RuntimeError(
                    "Playwright が未インストールです。\n"
                    "pip install playwright && playwright install chromium を実行してください。"
                )
            if "playwright" not in _pw_context:
                _pw_context["playwright"] = sync_playwright().start()
            if "browser" not in _pw_context or not _pw_context["browser"].is_connected():
                _pw_context["browser"] = _pw_context["playwright"].chromium.launch(headless=False)
            _pw_context["page"] = _pw_context["browser"].new_page()
        return _pw_context["page"]

@_browser_registry.register(
    name="browser_navigate",
    description="ブラウザで指定URLに遷移する。ログインページや動的サイトの操作に使用。",
    parameters={
        "type": "object",
        "properties": {
            "url": {"type": "string", "description": "遷移先のURL"},
            "wait_ms": {"type": "integer", "description": "遷移後の待機ミリ秒（デフォルト1000）", "default": 1000}
        },
        "required": ["url"]
    }
)
def browser_navigate(url: str, wait_ms: int = 1000) -> str:
    try:
        page = _get_browser_page()
        page.goto(url, timeout=30000)
        page.wait_for_timeout(wait_ms)
        return f"遷移完了: {page.url}\nタイトル: {page.title()}"
    except Exception as e:
        return f"browser_navigate エラー: {e}"

@_browser_registry.register(
    name="browser_click",
    description="CSSセレクタまたはテキストで要素をクリックする。ボタン・リンク・メニュー操作に使用。",
    parameters={
        "type": "object",
        "properties": {
            "selector": {"type": "string", "description": "CSSセレクタ（例: button#submit）またはテキスト（例: text=ログイン）"},
            "wait_ms": {"type": "integer", "description": "クリック後の待機ミリ秒（デフォルト500）", "default": 500}
        },
        "required": ["selector"]
    }
)
def browser_click(selector: str, wait_ms: int = 500) -> str:
    try:
        page = _get_browser_page()
        page.click(selector, timeout=10000)
        page.wait_for_timeout(wait_ms)
        return f"クリック完了: {selector}\n現在のURL: {page.url}"
    except Exception as e:
        return f"browser_click エラー: {e}"

@_browser_registry.register(
    name="browser_type",
    description="入力フィールドにテキストを入力する。フォーム記入・検索ボックス入力に使用。",
    parameters={
        "type": "object",
        "properties": {
            "selector": {"type": "string", "description": "入力先のCSSセレクタ（例: input[name=email]）"},
            "text": {"type": "string", "description": "入力するテキスト"},
            "clear_first": {"type": "boolean", "description": "入力前に既存テキストを消去するか（デフォルトtrue）", "default": True}
        },
        "required": ["selector", "text"]
    }
)
def browser_type(selector: str, text: str, clear_first: bool = True) -> str:
    try:
        page = _get_browser_page()
        if clear_first:
            page.fill(selector, text, timeout=10000)
        else:
            page.type(selector, text, timeout=10000)
        return f"入力完了: {selector} ← \"{text[:50]}\""
    except Exception as e:
        return f"browser_type エラー: {e}"

@_browser_registry.register(
    name="browser_get_text",
    description="ページ全体またはセレクタで指定した要素のテキストを取得する。",
    parameters={
        "type": "object",
        "properties": {
            "selector": {"type": "string", "description": "取得対象のCSSセレクタ（省略時はページ全体）"},
            "max_chars": {"type": "integer", "description": "最大取得文字数（デフォルト5000）", "default": 5000}
        }
    }
)
def browser_get_text(selector: str = "", max_chars: int = 5000) -> str:
    try:
        page = _get_browser_page()
        if selector:
            text = page.inner_text(selector, timeout=10000)
        else:
            text = page.inner_text("body", timeout=10000)
        truncated = text[:max_chars]
        suffix = f"\n... (全{len(text):,}文字中{max_chars:,}文字を表示)" if len(text) > max_chars else ""
        return f"[URL: {page.url}]\n{truncated}{suffix}"
    except Exception as e:
        return f"browser_get_text エラー: {e}"

@_browser_registry.register(
    name="browser_screenshot",
    description="現在のブラウザ画面のスクリーンショットをファイルに保存する。",
    parameters={
        "type": "object",
        "properties": {
            "path": {"type": "string", "description": "保存先ファイルパス（省略時は ./screenshot.png）"}
        }
    }
)
def browser_screenshot(path: str = "./screenshot.png") -> str:
    try:
        page = _get_browser_page()
        page.screenshot(path=path, full_page=True)
        return f"スクリーンショット保存: {path}\nURL: {page.url}"
    except Exception as e:
        return f"browser_screenshot エラー: {e}"

@_browser_registry.register(
    name="browser_close",
    description="ブラウザを閉じてリソースを解放する。セッション終了時に呼ぶ。",
    parameters={"type": "object", "properties": {}}
)
def browser_close() -> str:
    try:
        if "browser" in _pw_context and _pw_context["browser"].is_connected():
            _pw_context["browser"].close()
        if "playwright" in _pw_context:
            _pw_context["playwright"].stop()
        _pw_context.clear()
        return "ブラウザを閉じました。"
    except Exception as e:
        return f"browser_close エラー: {e}"

_BROWSER_TOOL_NAMES = [
    "browser_navigate", "browser_click", "browser_type",
    "browser_get_text", "browser_screenshot", "browser_close",
]

def enable_browser_tools() -> str:
    for name in _BROWSER_TOOL_NAMES:
        tools.copy_tool(name, _browser_registry)
    return f"ブラウザツール有効化 ({len(_BROWSER_TOOL_NAMES)} 本)"

def disable_browser_tools() -> str:
    for name in _BROWSER_TOOL_NAMES:
        tools.unregister(name)
    return "ブラウザツール無効化"

def browser_tools_enabled() -> bool:
    return "browser_navigate" in tools._tools


